// ── Logic Engine — Conditional Quiz Branching ────────────────────────────────
//
// Pure functions only. No DB access. No side effects. No `any` types.
// All functions are exported and safe to call from server-side route handlers.

// ── Types ─────────────────────────────────────────────────────────────────────

/**
 * A single branching rule stored inside a question's `logic` JSON field.
 * When the shopper selects `answerId`, navigation jumps to `goto`.
 */
export interface LogicRule {
  answerId: string;
  goto: string; // a questionId, or the sentinel string "results"
}

/**
 * The parsed shape of the `Question.logic` JSON field.
 */
export interface QuestionLogic {
  rules: LogicRule[];
}

/**
 * A lightweight representation of a question used by the branching engine.
 * Consumers build this from Prisma Question + Answer records.
 */
export interface QuestionNode {
  id: string;
  position: number;
  logic: QuestionLogic;
  answers: Array<{
    id: string;
    nextQuestionId: string | null;
  }>;
}

/**
 * The result of evaluating branching for one question.
 * `nextQuestionId === null` means the quiz is complete and should show results.
 */
export interface BranchingResult {
  nextQuestionId: string | null; // null → go to results
  isEnd: boolean;
}

/**
 * A single recorded answer from a shopper, used by `buildQuestionOrder`.
 * Supply either `answerId` (single-select) or `answerIds` (multi-select) or neither
 * (open-ended text/slider/email questions that don't drive branching).
 */
export interface RecordedAnswer {
  questionId: string;
  answerId?: string;
  answerIds?: string[];
}

/**
 * A validation error produced by `validateLogicRules`.
 */
export interface LogicValidationError {
  questionId: string;
  error: string;
}

// ── parseLogic ────────────────────────────────────────────────────────────────

/**
 * Safely parses the `Question.logic` JSON string.
 * Returns `{ rules: [] }` on any parse failure or invalid shape.
 *
 * Law 6: all JSON field reads use try/catch with documented fallback.
 */
export function parseLogic(logicJson: string): QuestionLogic {
  try {
    const parsed: unknown = JSON.parse(logicJson);
    if (
      parsed !== null &&
      typeof parsed === "object" &&
      !Array.isArray(parsed) &&
      "rules" in parsed &&
      Array.isArray((parsed as Record<string, unknown>).rules)
    ) {
      const rawRules = (parsed as { rules: unknown[] }).rules;
      const rules: LogicRule[] = rawRules.reduce<LogicRule[]>((acc, rule) => {
        if (
          rule !== null &&
          typeof rule === "object" &&
          !Array.isArray(rule) &&
          typeof (rule as Record<string, unknown>).answerId === "string" &&
          typeof (rule as Record<string, unknown>).goto === "string"
        ) {
          acc.push({
            answerId: (rule as { answerId: string }).answerId,
            goto: (rule as { goto: string }).goto,
          });
        }
        return acc;
      }, []);
      return { rules };
    }
    return { rules: [] };
  } catch {
    return { rules: [] };
  }
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Sorts questions by `position` ascending (does not mutate the original array).
 */
function sortByPosition(questions: QuestionNode[]): QuestionNode[] {
  return [...questions].sort((a, b) => a.position - b.position);
}

/**
 * Returns the next sequential question after `currentId` in position order,
 * or `null` if `currentId` is the last question.
 */
function nextSequentialQuestion(
  currentId: string,
  sorted: QuestionNode[]
): string | null {
  const idx = sorted.findIndex((q) => q.id === currentId);
  if (idx === -1) return null;
  return sorted[idx + 1]?.id ?? null;
}

/**
 * Builds a Set of all question IDs for fast existence checks.
 */
function questionIdSet(questions: QuestionNode[]): Set<string> {
  return new Set(questions.map((q) => q.id));
}

// ── getNextQuestion ───────────────────────────────────────────────────────────

/**
 * Determines which question (or results) to navigate to after the shopper
 * answers a question.
 *
 * Priority order:
 *   1. Answer-level `nextQuestionId` on the selected answer (explicit skip-to).
 *   2. Question-level logic rules — first rule whose `answerId` matches a
 *      selected answer wins (rules are evaluated in array order).
 *      For multi-select, ANY matching rule triggers (first match in rule order).
 *   3. Default: next sequential question by `position`.
 *   4. If no next sequential question exists → results (`isEnd: true`).
 *
 * If a `goto` target references a questionId that does not exist in
 * `allQuestions`, the rule is ignored and evaluation falls through to the
 * next rule / sequential order.
 *
 * @param currentQuestion  The question being answered.
 * @param selectedAnswerId Single selected answerId, or `null` for open-ended.
 * @param selectedAnswerIds All selected answerIds for multi-select questions.
 * @param allQuestions     Full flat list of questions in the quiz.
 */
export function getNextQuestion(
  currentQuestion: QuestionNode,
  selectedAnswerId: string | null,
  selectedAnswerIds: string[],
  allQuestions: QuestionNode[]
): BranchingResult {
  const ids = questionIdSet(allQuestions);
  const sorted = sortByPosition(allQuestions);

  // Build the effective set of selected IDs, merging both params.
  const selectedSet = new Set<string>(selectedAnswerIds);
  if (selectedAnswerId !== null) selectedSet.add(selectedAnswerId);

  // ── Priority 1: Answer-level nextQuestionId ──────────────────────────────
  for (const selectedId of selectedSet) {
    const answer = currentQuestion.answers.find((a) => a.id === selectedId);
    if (answer?.nextQuestionId) {
      if (ids.has(answer.nextQuestionId)) {
        return { nextQuestionId: answer.nextQuestionId, isEnd: false };
      }
      // nextQuestionId points to a deleted question — fall through.
    }
  }

  // ── Priority 2: Question-level logic rules ───────────────────────────────
  for (const rule of currentQuestion.logic.rules) {
    if (!selectedSet.has(rule.answerId)) continue;

    if (rule.goto === "results") {
      return { nextQuestionId: null, isEnd: true };
    }

    if (ids.has(rule.goto)) {
      return { nextQuestionId: rule.goto, isEnd: false };
    }
    // Goto references a non-existent question — ignore this rule and continue.
  }

  // ── Priority 3 & 4: Sequential fallthrough ───────────────────────────────
  const next = nextSequentialQuestion(currentQuestion.id, sorted);
  if (next === null) {
    return { nextQuestionId: null, isEnd: true };
  }
  return { nextQuestionId: next, isEnd: false };
}

// ── buildQuestionOrder ────────────────────────────────────────────────────────

/**
 * Simulates a shopper's path through the quiz and returns the ordered list of
 * questionIds they would actually see, given a specific set of answers.
 *
 * Questions that are skipped over by branching rules are excluded from the
 * returned array.
 *
 * A maximum of 100 iterations is enforced to prevent infinite loops caused by
 * circular logic graphs (cycle detection via `validateLogicRules` is the
 * authoritative guard, but this limit protects the runtime).
 *
 * @param questions  All questions in the quiz.
 * @param answers    The shopper's recorded answers, in submission order.
 *                   Answers for questions not encountered during traversal are
 *                   silently ignored.
 */
export function buildQuestionOrder(
  questions: QuestionNode[],
  answers: RecordedAnswer[]
): string[] {
  if (questions.length === 0) return [];

  const sorted = sortByPosition(questions);
  const questionMap = new Map<string, QuestionNode>(
    questions.map((q) => [q.id, q])
  );
  const answerMap = new Map<string, RecordedAnswer>(
    answers.map((a) => [a.questionId, a])
  );

  const visited: string[] = [];
  const visitedSet = new Set<string>();

  let currentId: string | null = sorted[0].id;
  let iterations = 0;
  const MAX_ITERATIONS = 100;

  while (currentId !== null && iterations < MAX_ITERATIONS) {
    iterations++;

    // Cycle guard: if we've already visited this question, stop.
    if (visitedSet.has(currentId)) break;

    const current = questionMap.get(currentId);
    if (!current) break; // Dangling reference — stop traversal.

    visited.push(currentId);
    visitedSet.add(currentId);

    const recorded = answerMap.get(currentId);
    const selectedAnswerId = recorded?.answerId ?? null;
    const selectedAnswerIds = recorded?.answerIds ?? [];

    const result = getNextQuestion(
      current,
      selectedAnswerId,
      selectedAnswerIds,
      questions
    );

    currentId = result.nextQuestionId;
  }

  return visited;
}

// ── validateLogicRules ────────────────────────────────────────────────────────

/**
 * Validates all branching rules across the quiz and returns a list of errors.
 *
 * Checks performed:
 *   - Invalid `goto` references (questionId that does not exist and is not
 *     the sentinel "results").
 *   - Rules referencing non-existent `answerId`s on the owning question.
 *   - Cycles detected via DFS (e.g. question A → B → A).
 *   - Answer-level `nextQuestionId` pointing to a non-existent question.
 *
 * Returns an empty array when the quiz graph is valid.
 */
export function validateLogicRules(
  questions: QuestionNode[]
): LogicValidationError[] {
  const errors: LogicValidationError[] = [];
  const ids = questionIdSet(questions);

  for (const question of questions) {
    const answerIds = new Set(question.answers.map((a) => a.id));

    // Validate question-level logic rules.
    for (const rule of question.logic.rules) {
      if (!answerIds.has(rule.answerId)) {
        errors.push({
          questionId: question.id,
          error: `Logic rule references non-existent answerId "${rule.answerId}".`,
        });
      }

      if (rule.goto !== "results" && !ids.has(rule.goto)) {
        errors.push({
          questionId: question.id,
          error: `Logic rule goto "${rule.goto}" references a question that does not exist.`,
        });
      }
    }

    // Validate answer-level nextQuestionId overrides.
    for (const answer of question.answers) {
      if (answer.nextQuestionId !== null && answer.nextQuestionId !== undefined) {
        if (!ids.has(answer.nextQuestionId)) {
          errors.push({
            questionId: question.id,
            error: `Answer "${answer.id}" has nextQuestionId "${answer.nextQuestionId}" which references a question that does not exist.`,
          });
        }
      }
    }
  }

  // ── Cycle detection via iterative DFS ─────────────────────────────────────
  //
  // Build an adjacency list of all possible next-question edges, then run DFS
  // from every unvisited node, tracking the recursion stack.

  type EdgeSet = Map<string, string[]>;

  const graph: EdgeSet = new Map<string, string[]>();

  for (const question of questions) {
    const edges: string[] = [];

    // Edges from logic rules (skip-to references only; "results" is a sink).
    for (const rule of question.logic.rules) {
      if (rule.goto !== "results" && ids.has(rule.goto)) {
        edges.push(rule.goto);
      }
    }

    // Edges from answer-level nextQuestionId overrides.
    for (const answer of question.answers) {
      if (answer.nextQuestionId && ids.has(answer.nextQuestionId)) {
        edges.push(answer.nextQuestionId);
      }
    }

    graph.set(question.id, edges);
  }

  const visited = new Set<string>();
  const inStack = new Set<string>();

  function dfs(nodeId: string): void {
    visited.add(nodeId);
    inStack.add(nodeId);

    for (const neighbor of graph.get(nodeId) ?? []) {
      if (inStack.has(neighbor)) {
        // Cycle detected — report on the question that closes the cycle.
        errors.push({
          questionId: nodeId,
          error: `Circular logic detected: question "${nodeId}" creates a cycle via "${neighbor}". Quiz activation is blocked until this is resolved.`,
        });
        continue;
      }
      if (!visited.has(neighbor)) {
        dfs(neighbor);
      }
    }

    inStack.delete(nodeId);
  }

  for (const question of questions) {
    if (!visited.has(question.id)) {
      dfs(question.id);
    }
  }

  return errors;
}

// ── getReachableQuestions ─────────────────────────────────────────────────────

/**
 * Returns the set of questionIds reachable from the first question (lowest
 * `position`) by following every possible branching path.
 *
 * This is a forward BFS/DFS that considers:
 *   - All logic rule `goto` targets (excluding the "results" sentinel).
 *   - All answer-level `nextQuestionId` overrides.
 *   - The default sequential successor (next by position).
 *
 * Unreachable questions (those whose IDs are NOT in the returned set) can never
 * be shown to a shopper under any answer combination and may be surfaced as
 * warnings in the logic editor.
 *
 * The starting question itself is always included in the returned set.
 */
export function getReachableQuestions(questions: QuestionNode[]): Set<string> {
  if (questions.length === 0) return new Set<string>();

  const sorted = sortByPosition(questions);
  const ids = questionIdSet(questions);
  const reachable = new Set<string>();
  const queue: string[] = [sorted[0].id];

  // BFS over all possible next-question edges.
  while (queue.length > 0) {
    const currentId = queue.shift()!;
    if (reachable.has(currentId)) continue;
    reachable.add(currentId);

    const current = sorted.find((q) => q.id === currentId);
    if (!current) continue;

    // Collect all possible successor question IDs from this node.
    const successors = new Set<string>();

    // 1. Answer-level nextQuestionId overrides.
    for (const answer of current.answers) {
      if (answer.nextQuestionId && ids.has(answer.nextQuestionId)) {
        successors.add(answer.nextQuestionId);
      }
    }

    // 2. Question-level logic rule gotos.
    for (const rule of current.logic.rules) {
      if (rule.goto !== "results" && ids.has(rule.goto)) {
        successors.add(rule.goto);
      }
    }

    // 3. Default sequential successor (only added if no answer or rule
    //    unconditionally overrides ALL paths — we add it conservatively
    //    because not every answer necessarily has a rule or override).
    const sequential = nextSequentialQuestion(currentId, sorted);
    if (sequential !== null) {
      successors.add(sequential);
    }

    for (const successor of successors) {
      if (!reachable.has(successor)) {
        queue.push(successor);
      }
    }
  }

  return reachable;
}
